def strategy(history, rng):
    n = len(history)
    if n >= 99:
        return 'D'
    if n == 0:
        return 'C'

    my_last, opp_last = history[-1]

    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    start = n - 10
    if start < 0:
        start = 0

    recent10_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            recent10_c += 1

    total_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            total_c += 1

    if opp_last == 'D':
        if my_last == 'C' and n >= 2:
            pm, po = history[-2]
            if pm == 'D' and po == 'C':
                return 'C'

        if streak == 5 and total_c > 0:
            return 'C'

        return 'D'

    if recent10_c <= 1 and total_c * 3 <= n:
        return 'D'

    if my_last == 'D':
        c_after_d = 0
        d_after_d = 0
        for i in range(n - 1):
            if history[i][0] == 'D':
                if history[i + 1][1] == 'C':
                    c_after_d += 1
                else:
                    d_after_d += 1

        if c_after_d > d_after_d and recent10_c >= 5:
            return 'D'

    return 'C'
